create table if not exists schedule_buildings(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code(),name text not null,code text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(institution_code,name));
alter table classrooms add column if not exists building_id uuid references schedule_buildings(id),add column if not exists floor smallint,add column if not exists max_simultaneous_activities smallint not null default 1 check(max_simultaneous_activities>=1),add column if not exists aggregate_capacity_enforced boolean not null default true;
create table if not exists schedule_period_breaks(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code(),time_profile_id uuid not null references schedule_time_profiles(id) on delete cascade,after_period smallint not null check(after_period>=1),minutes smallint not null default 0 check(minutes>=0),transfer_allowed boolean not null default true,unique(institution_code,time_profile_id,after_period));
create table if not exists schedule_building_travel(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code(),from_building_id uuid not null references schedule_buildings(id) on delete cascade,to_building_id uuid not null references schedule_buildings(id) on delete cascade,minutes smallint not null check(minutes>=0),active boolean not null default true,check(from_building_id<>to_building_id),unique(institution_code,from_building_id,to_building_id));
create index if not exists idx_classrooms_building on classrooms(institution_code,building_id) where active;create index if not exists idx_schedule_building_travel on schedule_building_travel(institution_code,from_building_id,to_building_id) where active;
alter table schedule_buildings enable row level security;alter table schedule_period_breaks enable row level security;alter table schedule_building_travel enable row level security;
drop policy if exists schedule_buildings_read on schedule_buildings;create policy schedule_buildings_read on schedule_buildings for select to authenticated using(tenant_row_allowed(institution_code));drop policy if exists schedule_buildings_manage on schedule_buildings;create policy schedule_buildings_manage on schedule_buildings for all to authenticated using((has_permission('classrooms.manage') or has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code)) with check((has_permission('classrooms.manage') or has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code));
drop policy if exists schedule_period_breaks_read on schedule_period_breaks;create policy schedule_period_breaks_read on schedule_period_breaks for select to authenticated using(tenant_row_allowed(institution_code));drop policy if exists schedule_period_breaks_manage on schedule_period_breaks;create policy schedule_period_breaks_manage on schedule_period_breaks for all to authenticated using((has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code)) with check((has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code));
drop policy if exists schedule_building_travel_read on schedule_building_travel;create policy schedule_building_travel_read on schedule_building_travel for select to authenticated using(tenant_row_allowed(institution_code));drop policy if exists schedule_building_travel_manage on schedule_building_travel;create policy schedule_building_travel_manage on schedule_building_travel for all to authenticated using((has_permission('classrooms.manage') or has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code)) with check((has_permission('classrooms.manage') or has_permission('schedule.rules') or is_manager_or_admin()) and tenant_row_allowed(institution_code));
create or replace function get_schedule_building_travel_minutes_v1(p_from uuid,p_to uuid) returns smallint language sql stable as $$select case when p_from is null or p_to is null or p_from=p_to then 0::smallint else coalesce((select minutes from schedule_building_travel where active and tenant_row_allowed(institution_code) and ((from_building_id=p_from and to_building_id=p_to) or (from_building_id=p_to and to_building_id=p_from)) order by case when from_building_id=p_from then 0 else 1 end limit 1),0::smallint) end$$;